entries.example:
var trust = New CertificateFile("C:\certs\bank-ca.pem");
var mine = New CertificateFile("C:\certs\client.pem", "key password");

var secure = New SecureConnection(mine, trust);      // предъявить свой, доверять только этому центру
var bank = New HTTPConnection("api.bank.example");
bank.SecureConnection = secure;                      // порт не задан: с защитой это 443

try {
    var response = bank.Get(New HTTPRequest("/v1/balance"));
    Message(response.StatusCode);
}
except {
    Message(ErrorDescription());   // ...the certificate file 'C:\certs\client.pem' could not be read...
}

var trust = New CertificateFile("C:\certs\bank-ca.pem");
var secure = New SecureConnection();
secure.TrustedCertificates = trust;
Message(secure.TrustedCertificates.Path);   // возвращается тем же

