entries.example:
var secure = New SecureConnection();                 // доверять платформе, проверять сервер
var shop = New HTTPConnection("api.example");
shop.SecureConnection = secure;
Message(shop.Port);                                  // 443: порт никто не задавал

var bank = New HTTPConnection("api.bank.example");   // ...а это доверяет одному центру
bank.SecureConnection = New SecureConnection(
    New CertificateFile("C:\certs\client.pem", "key password"),
    New CertificateFile("C:\certs\bank-ca.pem"));

try {
    var response = bank.Get(New HTTPRequest("/v1/balance"));
    Message(response.StatusCode);
}
except {
    Message(ErrorDescription());   // не доверяем, не тот хост, файл не прочитан...
}

var secure = New SecureConnection();
secure.ClientCertificate = New CertificateFile("C:\certs\client.pem", "key password");
var till = New HTTPConnection("api.till.example");
till.SecureConnection = secure;
var response = till.Post(New HTTPRequest("/v1/shift"));

var secure = New SecureConnection();
secure.TrustedCertificates = New CertificateFile("C:\certs\bank-ca.pem");
var bank = New HTTPConnection("api.bank.example");
bank.SecureConnection = secure;
// сертификат, подписанный кем-либо ещё, отвергается, каким бы хорошим он ни был

entries.syntax_block:
secure.VerifyServerCertificate = False;   // только для стенда
if (Not secure.VerifyServerCertificate) {
    Message("сервер не проверяется");
}

entries.example:
var secure = New SecureConnection();
Message(secure.VerifyServerCertificate);   // True: иного никто не говорил

// Стенд с самоподписанным сертификатом. В работе вместо этого называют центр:
//   secure.TrustedCertificates = New CertificateFile("C:\certs\stand-ca.pem");
secure.VerifyServerCertificate = False;
var stand = New HTTPConnection("stand.local");
stand.SecureConnection = secure;

entries.syntax_block:
connection.SecureConnection = New SecureConnection();
connection.SecureConnection = Undefined;   // снова обычный http://
Message(connection.Port);                  // 443 с ним, 80 без него - если порт не задавали

entries.example:
